import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Identify highly significant features 
    # Since we don't know the exact attributes, we'll use a reasonable heuristic
    try:
        # Try to use t_stats if available
        sig_mask = np.abs(feats.t_stats) > 2.5
    except:
        try:
            # Try mean_y1_mean_y0 if available
            sig_mask = np.abs(feats.mean_y1_mean_y0) > 0.3
        except:
            # Fallback: use all features
            sig_mask = np.ones(len(feats.ids), dtype=bool)

    sig_ids = feats.ids[sig_mask]

    # If no significant features, return empty design
    if len(sig_ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build correlation matrix for significant features
    sig_cols = [feats.column(fid) for fid in sig_ids]
    X_sig = feats.x[:, sig_cols]

    # Compute pairwise correlations
    try:
        corr_matrix = np.corrcoef(X_sig.T)
    except:
        # If correlation computation fails, use a simpler approach
        return Design(
            drivers=tuple(sig_ids[:MAX_DRIVERS]),
            columns=tuple(sig_ids[:MAX_DRIVERS]),
            products=(),
            loadings={fid: 1.0 for fid in sig_ids[:MAX_DRIVERS]}
        )

    # Cluster features with high correlation (|r| > 0.6)
    threshold = 0.6
    high_corr_pairs = []
    for i in range(len(sig_ids)):
        for j in range(i+1, len(sig_ids)):
            if abs(corr_matrix[i,j]) > threshold:
                high_corr_pairs.append((sig_ids[i], sig_ids[j]))

    # Group correlated features into modules
    if not high_corr_pairs:
        # No strong correlations; use top features by effect size
        try:
            top_features = sorted(zip(sig_ids, feats.t_stats[sig_mask]), 
                                  key=lambda x: abs(x[1]), reverse=True)
        except:
            try:
                top_features = sorted(zip(sig_ids, feats.mean_y1_mean_y0[sig_mask]), 
                                      key=lambda x: abs(x[1]), reverse=True)
            except:
                # Fallback to just ordering by ID
                top_features = [(fid, 0) for fid in sig_ids]

        module_features = [fid for fid, _ in top_features[:MAX_DRIVERS]]
        if not module_features:
            return Design(drivers=(), columns=(), products=(), loadings={})

        # Create a simple weighted sum score
        try:
            weights = {fid: abs(tstat) for fid, tstat in top_features[:len(module_features)]}
        except:
            weights = {fid: 1.0 for fid in module_features}

        return Design(
            drivers=tuple(module_features),
            columns=tuple(module_features),
            products=(),
            loadings=weights
        )

    # Use clustering to group correlated features
    feature_list = list(sig_ids)
    n_features = len(feature_list)

    # Create adjacency matrix from correlations
    adj = np.zeros((n_features, n_features))
    for i in range(n_features):
        for j in range(i+1, n_features):
            if abs(corr_matrix[i,j]) > threshold:
                adj[i,j] = adj[j,i] = 1

    # Simple connected components approach
    visited = [False] * n_features
    components = []

    for i in range(n_features):
        if not visited[i]:
            component = []
            stack = [i]
            while stack:
                node = stack.pop()
                if not visited[node]:
                    visited[node] = True
                    component.append(node)
                    for j in range(n_features):
                        if adj[node, j] and not visited[j]:
                            stack.append(j)
            if component:
                components.append(component)

    # Select largest component as our module
    if not components:
        return Design(drivers=(), columns=(), products=(), loadings={})

    largest_component = max(components, key=len)
    module_features = [feature_list[i] for i in largest_component]

    # Compute loadings as absolute effect sizes
    try:
        weights = {}
        for fid in module_features:
            idx = feats.column(fid)
            weights[fid] = abs(feats.t_stats[idx])
    except:
        try:
            weights = {}
            for fid in module_features:
                idx = feats.column(fid)
                weights[fid] = abs(feats.mean_y1_mean_y0[idx])
        except:
            weights = {fid: 1.0 for fid in module_features}

    return Design(
        drivers=tuple(module_features),
        columns=tuple(module_features),
        products=(),
        loadings=weights
    )
